SELECT u.School, u.Location 
FROM university u 
WHERE u.Affiliation = 'Public';

SELECT Address 
FROM Locations 
WHERE Location_Name = 'UK Gallery';

SELECT * 
FROM employees 
WHERE salary BETWEEN (SELECT MIN(salary) FROM employees) AND 2500;

SELECT COUNT(*) 
FROM trip 
WHERE start_station_name IN (
    SELECT name FROM station WHERE city = 'Mountain View'
)
AND end_station_name IN (
    SELECT name FROM station WHERE city = 'Palo Alto'
);

SELECT b.Book_Title, b.Author_or_Editor 
FROM book_club b 
WHERE b.Year > 1989;

SELECT email_address, date_of_birth 
FROM Customers 
WHERE first_name = 'Carole';

SELECT COUNT(*) 
FROM student_1 
WHERE Classroom = (SELECT Classroom FROM teachers WHERE LastName = 'LORIA' AND FirstName = 'ONDERSMA');

SELECT flno, origin, destination 
FROM flight 
ORDER BY origin ASC;

SELECT DISTINCT a.fname 
FROM Authors a 
ORDER BY a.fname ASC;

SELECT DISTINCT m.Country, fme.Year
FROM film_market_estimation fme
JOIN market m ON fme.Market_ID = m.Market_ID;

SELECT a.name
FROM ACCOUNTS a
ORDER BY a.name ASC;

SELECT DISTINCT c.catalog_publisher 
FROM Catalogs c 
WHERE c.catalog_publisher LIKE '%Murray%';

SELECT DISTINCT Name 
FROM Medication 
ORDER BY Name ASC;

SELECT Election_Cycle, COUNT(*) AS Number_of_Voting_Records
FROM Voting_record
GROUP BY Election_Cycle;

SELECT e.FIRST_NAME || ' ' || e.LAST_NAME AS full_name, e.HIRE_DATE, e.SALARY, e.DEPARTMENT_ID
FROM employees e
WHERE e.FIRST_NAME NOT LIKE '%M%';

SELECT Official_Name 
FROM city 
ORDER BY Population DESC;

SELECT DISTINCT p.product_name
FROM Products p
ORDER BY p.product_name ASC;

SELECT Card_Number, Name, Hometown 
FROM member 
ORDER BY Level DESC;

SELECT p.Age 
FROM people p 
WHERE p.Height = (SELECT MAX(Height) FROM people);

SELECT organization_name 
FROM Organizations 
ORDER BY date_formed;

SELECT hotels.pets_allowed_yn, AVG(hotels.price_range) AS avg_price
FROM hotels
GROUP BY hotels.pets_allowed_yn;

SELECT customer_phone AS phone_number FROM Customers
UNION
SELECT supplier_phone AS phone_number FROM Suppliers;

SELECT DISTINCT a.name, a.nationality
FROM architect a
JOIN mill m ON a.id = m.architect_id;

SELECT DISTINCT c.customer_first_name, c.customer_last_name
FROM Customers c
JOIN Accounts a ON c.customer_id = a.customer_id;

SELECT DISTINCT Sponsor_name 
FROM player 
WHERE Residence IN ('Brandon', 'Birtle');

SELECT Founder 
FROM Manufacturers 
WHERE Name LIKE 'S%';

SELECT roomName, RoomId 
FROM Rooms 
WHERE basePrice > 160 AND maxOccupancy > 2;

SELECT Name 
FROM channel 
ORDER BY Rating_in_percent DESC;

SELECT m.Trade_Name, COUNT(m.id) AS medicine_count
FROM medicine m
GROUP BY m.Trade_Name;

SELECT AVG(u.Enrollment) 
FROM university u 
WHERE u.Founded < 1850;

SELECT Carrier
FROM phone
WHERE Price = (SELECT MAX(Price) FROM phone);

SELECT AVG(price_in_euros) AS average_price_euro, MIN(price_in_euros) AS minimum_price_euro
FROM Catalog_Contents
WHERE price_in_euros IS NOT NULL;

SELECT DISTINCT s.student_id
FROM Students s
JOIN Student_Course_Attendance a ON s.student_id = a.student_id;

SELECT p.first_name, p.last_name
FROM People p
JOIN Candidates c ON p.person_id = c.candidate_id;

SELECT ClubLocation 
FROM Club 
WHERE ClubName = 'Pen and Paper Gaming';

SELECT w.Name
FROM wrestler w
ORDER BY CAST(w.Days_held AS INTEGER) DESC;

SELECT Model_name 
FROM chip_model 
ORDER BY Launch_year;

SELECT DISTINCT Destruction_Authorised_by_Employee_ID AS Employee_ID
FROM Documents_to_be_Destroyed
WHERE Destruction_Authorised_by_Employee_ID IS NOT NULL;

SELECT p.Name 
FROM people p 
WHERE p.Height < (SELECT AVG(Height) FROM people);

SELECT DISTINCT u.School
FROM university u
WHERE u.Founded > 1850 OR u.Affiliation = 'Public';

SELECT transaction_type, COUNT(*) AS transaction_count
FROM Financial_Transactions
GROUP BY transaction_type;

SELECT COUNT(*) 
FROM branch 
WHERE membership_amount > (
    SELECT AVG(CAST(membership_amount AS REAL)) 
    FROM branch
);

SELECT DISTINCT Major 
FROM Student 
WHERE Sex = 'M';

SELECT Country, COUNT(*) AS NumberOfPeople
FROM people
GROUP BY Country;

SELECT Year, Book_Title, Publisher 
FROM book_club 
ORDER BY Year DESC;

SELECT p.Date, p.Location, p.Attendance
FROM performance p
WHERE p.Location IN ('TD Garden', 'Bell Centre');

SELECT COUNT(DISTINCT a.Artist_ID) 
FROM artist a 
INNER JOIN volume v ON a.Artist_ID = v.Artist_ID;

SELECT h.name 
FROM head h 
WHERE h.born_state != 'California';

SELECT a.Country, COUNT(*) AS airport_count
FROM airport a
GROUP BY a.Country;

SELECT MIN(problem_log_id) AS oldest_log_id, 
       (SELECT problem_id FROM Problem_Log WHERE problem_log_id = MIN(pl.problem_log_id)) AS problem_id
FROM Problem_Log pl;

SELECT COUNT(*) 
FROM Products 
WHERE product_price > (SELECT AVG(product_price) FROM Products);

SELECT t.Name, t.Location, t.Year_Opened
FROM track t
WHERE t.Seating > (SELECT AVG(Seating) FROM track);

SELECT DISTINCT s.name, s.installation_date 
FROM trip t 
JOIN station s ON t.end_station_id = s.id;

SELECT Delegate 
FROM election 
WHERE District = 1;

SELECT DISTINCT fname 
FROM Authors 
ORDER BY fname ASC;

SELECT d.District_name, d.City_Population
FROM district d
WHERE d.City_Population BETWEEN 200000 AND 2000000;

SELECT Publisher, COUNT(*) AS NumberOfPublications
FROM publication
GROUP BY Publisher;

SELECT AVG(Average_Attendance) 
FROM stadium 
WHERE Capacity_Percentage > 100;

SELECT course_id FROM section 
WHERE (semester = 'Fall' AND year = 2009) 
   OR (semester = 'Spring' AND year = 2010);

SELECT s.Shop_Name 
FROM shop s 
ORDER BY s.Open_Year ASC;

SELECT AVG(distance) AS avg_distance, AVG(price) AS avg_price
FROM flight
WHERE origin = 'Los Angeles';

SELECT transaction_type, SUM(transaction_amount) AS total_transaction_amount
FROM Financial_Transactions
GROUP BY transaction_type;

SELECT pName, HS 
FROM Player 
WHERE HS < 1500;

SELECT AVG(Damage_millions_USD) AS avg_damage, MAX(Damage_millions_USD) AS max_damage
FROM storm
WHERE Max_speed > 1000;

SELECT salary, manager_id 
FROM employees 
WHERE manager_id IS NOT NULL;

SELECT position, AVG(points) AS avg_points
FROM player
GROUP BY position;

SELECT Main_Industry, SUM(Market_Value) AS Total_Market_Value
FROM company
GROUP BY Main_Industry;

SELECT SUM(CRS_CREDIT) AS total_credits_offered
FROM COURSE
JOIN DEPARTMENT ON COURSE.DEPT_CODE = DEPARTMENT.DEPT_CODE;

SELECT COUNT(*) 
FROM Ref_Colors c
WHERE c.color_code NOT IN (SELECT DISTINCT color_code FROM Products);

SELECT Budget_Type_Description 
FROM Ref_Budget_Codes 
WHERE Budget_Type_Code = 'ORG';

SELECT AVG(s.lat) AS avg_latitude, AVG(s.long) AS avg_longitude
FROM trip t
JOIN station s ON t.start_station_id = s.id;

SELECT song_name 
FROM song 
WHERE genre_is = 'modern' OR languages = 'English';

SELECT c.Company, c.Headquarters 
FROM company c 
ORDER BY c.Market_Value DESC;

SELECT m.Name 
FROM Manufacturers m 
WHERE m.Revenue > (SELECT AVG(Revenue) FROM Manufacturers);

SELECT Reviewer.name, Movie.title
FROM Reviewer
CROSS JOIN Movie;

SELECT COUNT(DISTINCT c.customer_id) 
FROM Customers c 
INNER JOIN Accounts a ON c.customer_id = a.customer_id;

SELECT Major, COUNT(*) AS student_count 
FROM Student 
GROUP BY Major;

SELECT c.cust_name, c.acc_bal 
FROM customer c 
WHERE c.cust_name LIKE '%a%';

SELECT DISTINCT c.state
FROM College c
WHERE c.enr < (SELECT MAX(c2.enr) FROM College c2);

SELECT d.dept_name, d.building
FROM department d
WHERE d.budget > (SELECT AVG(budget) FROM department);

SELECT Classroom, COUNT(*) AS StudentCount
FROM list
GROUP BY Classroom;

SELECT m.Founder, SUM(m.Revenue) AS TotalRevenue
FROM Manufacturers m
GROUP BY m.Founder;

SELECT COUNT(*) 
FROM Customer 
WHERE Email LIKE '%gmail.com%';

SELECT ship.Type, AVG(ship.Tonnage) AS Average_Tonnage
FROM ship
GROUP BY ship.Type;

SELECT Rank, COUNT(*) AS captain_count 
FROM captain 
GROUP BY Rank;

SELECT Sex, AVG(Age) AS average_age, MAX(Age) AS oldest_age
FROM Student
GROUP BY Sex;

SELECT document_name 
FROM Documents 
WHERE document_name LIKE '%CV%';

SELECT AVG(distance) AS avg_distance, AVG(price) AS avg_price
FROM flight
WHERE origin = 'LA';

SELECT Marketing_Region_Descriptrion 
FROM Marketing_Regions 
WHERE Marketing_Region_Name = 'China';

SELECT p.Minister
FROM party p
WHERE p.Party_name != 'Progress Party';

SELECT s.Name
FROM Ship s
WHERE EXISTS (
    SELECT 1 FROM captain c1
    WHERE c1.Ship_ID = s.Ship_ID AND c1.Rank = 'Midshipman'
)
AND EXISTS (
    SELECT 1 FROM captain c2
    WHERE c2.Ship_ID = s.Ship_ID AND c2.Rank = 'Lieutenant'
);

SELECT p.Name 
FROM people p 
WHERE p.People_ID NOT IN (
    SELECT c.People_ID 
    FROM candidate c
);

SELECT AVG(s.rating) AS avg_rating, AVG(s.resolution) AS avg_resolution
FROM song s
WHERE s.languages LIKE '%Bangla%';

SELECT AVG(student_capacity) AS average_capacity, SUM(student_capacity) AS total_capacity
FROM Dorm
WHERE gender = 'X';

SELECT p.product_category_code, AVG(p.product_price) AS avg_price
FROM Products p
GROUP BY p.product_category_code;

SELECT ce.catalog_entry_name 
FROM Catalog_Contents ce 
WHERE ce.product_stock_number LIKE '2%';

SELECT bedType, AVG(basePrice) AS avg_base_price
FROM Rooms
GROUP BY bedType;

SELECT GameID, SUM(Hours_Played) AS Total_Hours_Played
FROM Plays_Games
GROUP BY GameID;

SELECT Team, COUNT(*) AS technician_count 
FROM technician 
GROUP BY Team;

SELECT Rank, COUNT(*) AS NumberOfFaculty 
FROM Faculty 
GROUP BY Rank;

SELECT e.first_name || ' ' || e.last_name AS full_name, e.salary
FROM employees e
WHERE e.salary < 6000;

SELECT COUNT(*) AS draft_copy_count
FROM Draft_Copies
WHERE document_id = 2;

SELECT s.Name 
FROM Ship s 
ORDER BY s.Built_Year, s.Class;

SELECT a.name, a.city, a.country, a.elevation 
FROM airports a 
WHERE a.city = 'New York';

SELECT Position, COUNT(DISTINCT Player) AS Player_Count
FROM match_season
GROUP BY Position;

SELECT date_valid_from, date_valid_to 
FROM Customers_Cards 
WHERE card_number = '4560596484842';

SELECT County_name 
FROM county 
ORDER BY County_name DESC;

SELECT date_test_taken 
FROM Student_Tests_Taken 
WHERE test_result = 'Pass';

SELECT c.Name, c.Location 
FROM cinema c 
WHERE c.Capacity > (SELECT AVG(Capacity) FROM cinema);

SELECT catalog_level_name, catalog_level_number 
FROM Catalog_Structure 
WHERE catalog_level_number BETWEEN 5 AND 10;

SELECT COUNT(*) 
FROM SAVINGS 
WHERE balance > (SELECT AVG(balance) FROM SAVINGS);

SELECT hotel_id, star_rating_code 
FROM Hotels 
ORDER BY price_range ASC;

SELECT f.Title, fme.Type
FROM film f
JOIN film_market_estimation fme ON f.Film_ID = fme.Film_ID;

SELECT DISTINCT Census_Ranking 
FROM city 
WHERE Status != 'Village';

SELECT Location 
FROM school 
ORDER BY Founded DESC;

SELECT Product_Name, AVG(Product_Price) AS Average_Price
FROM Products
GROUP BY Product_Name;

SELECT phone_number FROM Customers
UNION
SELECT phone_number FROM Staff;

SELECT c.country 
FROM customers c 
WHERE c.first_name = 'Roberto' AND c.last_name = 'Almeida';

SELECT a.Famous_Title 
FROM artist a 
WHERE a.Artist_ID NOT IN (SELECT v.Artist_ID FROM volume v);

SELECT p.Product_Name
FROM Products p
WHERE p.Product_ID NOT IN (
    SELECT pe.Product_ID
    FROM Products_in_Events pe
);

SELECT p.Age 
FROM people p 
WHERE p.Height = (SELECT MAX(Height) FROM people);

SELECT Country, COUNT(*) AS Number_of_Perpetrators
FROM perpetrator
GROUP BY Country;

SELECT email_address, date_of_birth 
FROM Customers 
WHERE first_name = 'Carole';

SELECT h.Name
FROM host h
WHERE h.Host_ID NOT IN (
  SELECT ph.Host_ID
  FROM party_host ph
);

SELECT Payment_Method_Code, Date_Payment_Made, Amount_Payment
FROM Payments
ORDER BY Date_Payment_Made ASC;

SELECT g.guest_first_name, ab.booking_start_date, ab.booking_end_date
FROM Apartment_Bookings ab
JOIN Guests g ON ab.guest_id = g.guest_id;

SELECT Campus 
FROM Campuses 
WHERE Year < 1800;

SELECT Position, AVG(Points) AS avg_points
FROM player
GROUP BY Position;

SELECT COUNT(*) 
FROM Students 
WHERE personal_name LIKE '%son%';

SELECT m.Location, a.Aircraft
FROM match m
JOIN aircraft a ON m.Winning_Aircraft = a.Aircraft_ID;

SELECT apt_number 
FROM Apartments 
ORDER BY CAST(room_count AS INTEGER) ASC;

SELECT p.Minister, p.Left_office
FROM party p
WHERE p.Left_office = (
  SELECT MAX(Left_office) FROM party
);

SELECT COUNT(DISTINCT pID) 
FROM Tryout 
WHERE pPos = 'goalie';

SELECT b.name 
FROM browser b 
ORDER BY b.market_share DESC;

SELECT m.Member_Name 
FROM member m 
WHERE m.Party_ID != (SELECT Party_ID FROM party WHERE Party_name = 'Progress Party');

SELECT BlockCode, COUNT(*) AS RoomCount
FROM Room
GROUP BY BlockCode;

SELECT b.Book_Title, b.Author_or_Editor
FROM book_club b
WHERE b.Year > 1989;

SELECT FirstName || ' ' || LastName AS FullName
FROM Employee
WHERE City = 'Calgary';

SELECT FIRST_NAME || ' ' || LAST_NAME AS full_name
FROM employees
WHERE SALARY > (SELECT SALARY FROM employees WHERE EMPLOYEE_ID = 163);

SELECT DISTINCT p.product_name
FROM Products p
ORDER BY p.product_name ASC;

SELECT a.account_id, c.customer_id, a.account_name
FROM Accounts a
JOIN Customers c ON a.customer_id = c.customer_id;

SELECT DISTINCT Type 
FROM film_market_estimation 
WHERE Year = 1995;

SELECT Venue 
FROM match 
ORDER BY Date DESC;

SELECT Location, COUNT(*) AS NumberOfPerformances
FROM performance
GROUP BY Location;

SELECT p.Name 
FROM phone p 
WHERE p.Carrier IN ('Sprint', 'TMobile');

SELECT COUNT(*) 
FROM Reservations 
WHERE FirstName = 'ROY' AND LastName = 'SWEAZY';

SELECT DISTINCT a.state_province_county, a.country
FROM Addresses a
WHERE a.zip_postcode LIKE '4%';

SELECT SUM(Degrees) 
FROM degrees 
WHERE Year BETWEEN 1998 AND 2002;

SELECT Name 
FROM wrestler 
WHERE CAST(Days_held AS INTEGER) < 100;

SELECT COUNT(*) 
FROM Rooms 
WHERE RoomId NOT IN (SELECT DISTINCT Room FROM Reservations);

SELECT DISTINCT b.bname 
FROM bank b 
INNER JOIN loan l ON b.branch_ID = l.branch_ID;

SELECT s.StuID, s.Fname, s.LName
FROM Student s
WHERE s.StuID NOT IN (
  SELECT ha.StuID
  FROM Has_Allergy ha
);

SELECT Student_Tests_Taken.date_test_taken 
FROM Student_Tests_Taken 
WHERE Student_Tests_Taken.test_result = 'Fail';

SELECT room_number, building 
FROM classroom 
WHERE capacity BETWEEN 50 AND 100;

SELECT COUNT(*) 
FROM artist 
WHERE Age > 46 AND Year_Join > 1990;

SELECT COUNT(*) 
FROM Scientists 
WHERE SSN NOT IN (SELECT Scientist FROM AssignedTo);

SELECT DISTINCT r.name 
FROM races r 
WHERE r.year BETWEEN 2014 AND 2017;

SELECT first_name, last_name, salary 
FROM employees 
WHERE first_name LIKE '%m';

SELECT Year, MAX(Price) AS MaxPrice, MAX(Score) AS MaxScore
FROM wine
GROUP BY Year;

SELECT shipping_agent_code 
FROM Ref_Shipping_Agents 
WHERE shipping_agent_name = 'UPS';

SELECT d.dorm_name
FROM Dorm d
WHERE d.gender = 'F';

SELECT COUNT(DISTINCT ct.council_tax_id)
FROM Council_Tax ct
JOIN Rent_Arrears ra ON ct.council_tax_id = ra.council_tax_id;

SELECT Case_burden 
FROM county_public_safety 
ORDER BY Population DESC;

SELECT Address, COUNT(*) AS Number_of_Members
FROM member
GROUP BY Address;

SELECT c.cust_name
FROM customer c
WHERE c.no_of_loans > 1;

SELECT COUNT(DISTINCT Bandmate) 
FROM Performance 
WHERE SongId = (SELECT SongId FROM Songs WHERE Title = 'Flash');

SELECT DISTINCT s.LName
FROM Student s
JOIN Voting_record v ON s.StuID = v.Class_President_Vote;

SELECT rt.Document_Type_Name, rt.Document_Type_Description, d.Document_Date
FROM Documents d
JOIN Ref_Document_Types rt ON d.Document_Type_Code = rt.Document_Type_Code;

SELECT s.Title 
FROM Songs s 
WHERE s.Title LIKE '%the%';

SELECT COUNT(*) 
FROM Allergy_Type 
WHERE AllergyType = 'animal';

SELECT DISTINCT f.Title, f.Studio
FROM film f
WHERE f.Studio LIKE '%Universal%';

SELECT u.name, u.email 
FROM user_profiles u 
WHERE u.name LIKE '%Swift%';

SELECT DISTINCT Carrier 
FROM device 
WHERE Software_Platform != 'Android';

SELECT Total_Points 
FROM gymnast 
ORDER BY Total_Points DESC;

SELECT DISTINCT a.lname 
FROM Authors a 
ORDER BY a.lname ASC;

SELECT SUM(Degrees) 
FROM degrees 
WHERE Year BETWEEN 1998 AND 2002;

SELECT payment_method_code, COUNT(*) AS customer_count
FROM Customers
GROUP BY payment_method_code;

SELECT Service_Type_Code 
FROM Services 
ORDER BY Service_Type_Code ASC;

SELECT SUM(Number_Deaths) AS Total_Deaths, SUM(Damage_millions_USD) AS Total_Damage
FROM storm
WHERE Max_speed > (SELECT AVG(Max_speed) FROM storm);
